.window-chrome {
  position: absolute;
  inset: 0 0 auto 0;
  height: 34px;
  display: flex;
  justify-content: flex-end;
  align-items: stretch;
  background: transparent;
  border: 0;
  pointer-events: none;
  z-index: 1200;
}
.window-chrome-drag {
  position: absolute;
  inset: 0 138px 0 0;
  background: transparent;
  pointer-events: auto;
}
.window-chrome button {
  pointer-events: auto;
  position: relative;
  z-index: 1;
  width: 46px;
  height: 34px;
  border: 0;
  border-radius: 0;
  background: transparent;
  color: var(--text-dim);
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  transition: background 120ms ease, color 120ms ease;
}
.window-chrome button:hover { background: var(--glass-h); color: var(--text); }
.window-chrome button.window-chrome-close:hover { background: #c42b1c; color: #fff; }

.app.sidebar-auto-hidden {
  grid-template-columns: 0 minmax(0, 1fr) !important;
}
.app.sidebar-auto-hidden .app-sidebar {
  position: absolute;
  inset: 0 auto 0 0;
  width: var(--sidebar-w);
  max-width: 85vw;
  height: 100vh;
  transform: translateX(-100%);
  opacity: 0;
  pointer-events: none;
  z-index: 1100;
  box-shadow: 12px 0 36px rgba(0, 0, 0, 0.28);
